#!/usr/bin/env python3
"""Call the Slack Web API from the command line.

Reads credentials from the environment:
  SLACK_TOKEN          Bot or user token (xoxb- / xoxp-) for Web API methods.
  SLACK_WEBHOOK_URL    Incoming webhook URL for the 'webhook' pseudo-method.

Usage:
  python3 slack_api.py <METHOD> [key=value ...] [--paginate]
  python3 slack_api.py webhook [text="..."] [blocks='[{...}]'] [--paginate]

Examples:
  python3 slack_api.py auth.test
  python3 slack_api.py chat.postMessage channel=C123456 text="Hello <@U999>!"
  python3 slack_api.py conversations.list types=public_channel --paginate
  python3 slack_api.py webhook text="Deploy finished" 

Notes:
  - Values are parsed as JSON when possible; otherwise treated as strings.
  - Output is a single JSON object on stdout. Failures exit non-zero.
  - --paginate follows response_metadata.next_cursor and merges the first
    top-level array found in the response.
"""
import json
import os
import sys
import urllib.error
import urllib.parse
import urllib.request

API_BASE = "https://slack.com/api/"
MAX_OUT = 8000  # keep stdout LLM-friendly


def die(error, code=1):
    print(json.dumps({"ok": False, "error": error}))
    sys.exit(code)


def parse_value(raw):
    try:
        return json.loads(raw)
    except (ValueError, TypeError):
        return raw


def http_post(url, data, headers):
    body = urllib.parse.urlencode(data).encode()
    req = urllib.request.Request(url, data=body, headers=headers, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.read().decode()
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode()
    except urllib.error.URLError as e:
        die("network error: %s" % e.reason)


def call_method(method, params, paginate):
    token = os.environ.get("SLACK_TOKEN", "").strip()
    if not token:
        die("SLACK_TOKEN is not set; export a bot (xoxb-) or user (xoxp-) token")
    headers = {"Authorization": "Bearer %s" % token}
    merged = {}
    pages = 0
    while True:
        pages += 1
        payload = dict(params)
        if merged.get("next_cursor"):
            payload["cursor"] = merged["next_cursor"]
        status, text = http_post(API_BASE + method, payload, headers)
        try:
            resp = json.loads(text)
        except ValueError:
            die("non-JSON response (HTTP %s): %s" % (status, text[:500]))
        if status != 200 or not resp.get("ok"):
            if isinstance(resp, dict) and resp.get("error"):
                die("method=%s HTTP=%s error=%s" % (method, status, resp["error"]))
            die("method=%s HTTP=%s response=%s" % (method, status, text[:500]))
        if not merged:
            merged = resp
        else:
            array_key = first_array_key(merged)
            if array_key:
                merged[array_key] = merged.get(array_key, []) + resp.get(array_key, [])
            merged["response_metadata"] = resp.get("response_metadata", {})
        if not paginate:
            break
        cursor = resp.get("response_metadata", {}).get("next_cursor", "")
        if not cursor:
            break
        params = dict(params)  # do not carry stale cursor
    if paginate and pages > 1:
        merged["_pages"] = pages
    return merged


def first_array_key(obj):
    for k, v in (obj or {}).items():
        if isinstance(v, list):
            return k
    return None


def call_webhook(params):
    url = os.environ.get("SLACK_WEBHOOK_URL", "").strip()
    if not url:
        die("SLACK_WEBHOOK_URL is not set; export the incoming webhook URL")
    status, text = http_post(url, params, {})
    if status != 200:
        die("webhook HTTP %s: %s" % (status, text[:500]))
    return {"ok": True, "webhook": True, "response": text[:200]}


def main(argv):
    if not argv or argv[0] in ("-h", "--help", "help"):
        print(__doc__)
        return 0
    paginate = "--paginate" in argv
    args = [a for a in argv if a != "--paginate"]
    method = args[0]
    params = {}
    for pair in args[1:]:
        if "=" not in pair:
            die("expected key=value, got: %s" % pair, code=2)
        k, _, v = pair.partition("=")
        params[k] = parse_value(v)
    if method == "webhook":
        result = call_webhook(params)
    else:
        result = call_method(method, params, paginate)
    out = json.dumps(result, ensure_ascii=False)
    if len(out) > MAX_OUT:
        out = out[:MAX_OUT] + '... (truncated)'
    print(out)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

